    do: {:pair, muro_fsm_subst(a, env), muro_fsm_subst(b, env)}

  defp muro_fsm_subst({:rec, fields}, env) when is_list(fields) do
    {:rec, Enum.map(fields, fn {name, ty} -> {name, muro_fsm_subst(ty, env)} end)}
  end

  defp muro_fsm_subst({:vec, elem, ix}, env) do
    {:vec, muro_fsm_subst(elem, env), muro_fsm_subst_ix(ix, env)}
  end

  defp muro_fsm_subst({:dat, name, args}, env) do
    {:dat, name, Enum.map(args, &muro_fsm_subst(&1, env))}
  end

  defp muro_fsm_subst(ty, _env), do: ty

  defp muro_fsm_subst_ix({:var, name}, env) do
    case Map.get(env, name) do
      n when is_integer(n) and n >= 0 -> {:lit, n}
      _ -> {:var, name}
    end
  end

  defp muro_fsm_subst_ix({:suc, inner}, env) do
    case muro_fsm_subst_ix(inner, env) do
      {:lit, n} -> {:lit, n + 1}
      other -> {:suc, other}
    end
  end

  defp muro_fsm_subst_ix(ix, _env), do: ix

  defp muro_fsm_desc(:nat) do
    if "Nat" in muro_fsm_reprs(), do: {:repr, :nat, "Nat"}, else: :nat
  end

  defp muro_fsm_desc(:bit), do: :bit
  defp muro_fsm_desc(:unit), do: :unit
  defp muro_fsm_desc({:pair, a, b}), do: {:pair, muro_fsm_desc(a), muro_fsm_desc(b)}

  defp muro_fsm_desc({:rec, fields}) when is_list(fields) do
    {:record, Enum.map(fields, fn {name, ty} -> {name, muro_fsm_desc(ty)} end)}
  end

  defp muro_fsm_desc({:vec, elem, {:lit, n}}) when is_integer(n) do
    {:vec, muro_fsm_desc(elem), n}
  end

  defp muro_fsm_desc({:vec, elem, _}), do: {:vec, muro_fsm_desc(elem), 0}

  defp muro_fsm_desc({:dat, name, []}) do
    shown = {:data, name, []}
    if name in muro_fsm_reprs(), do: {:repr, shown, name}, else: shown
  end

  defp muro_fsm_desc({:dat, name, args}) when is_list(args) do
    {:data, name, Enum.map(args, &muro_fsm_desc/1)}
  end

  defp muro_fsm_desc(other), do: other

  defp muro_fsm_to_emitted(n, :nat) when is_integer(n) and n >= 0, do: {:ok, n}
  defp muro_fsm_to_emitted(_, :nat), do: :error
  defp muro_fsm_to_emitted(bit, :bit) when bit in [:b0, :b1], do: {:ok, bit}
  defp muro_fsm_to_emitted(:tt, :unit), do: {:ok, :tt}

  defp muro_fsm_to_emitted({x, y}, {:pair, a, b}) do
    case muro_fsm_to_emitted(x, a) do
      {:ok, x} ->
        case muro_fsm_to_emitted(y, b) do
          {:ok, y} -> {:ok, {x, y}}
          other -> other
        end

      other ->
        other
    end
  end

  defp muro_fsm_to_emitted(map, {:rec, fields}) when is_list(fields) and is_map(map) do
    muro_fsm_emit_rec(fields, map, [])
  end

  defp muro_fsm_to_emitted(list, {:vec, elem, _ix}) when is_list(list) do
    muro_fsm_emit_list(list, elem, [])
  end

  defp muro_fsm_to_emitted(value, {:dat, name, args}) when is_list(args) do
    muro_fsm_emit_dat(value, name, args)
  end

  defp muro_fsm_to_emitted(_, _), do: :error

  defp muro_fsm_emit_dat(value, name, args) do
    case Map.get(muro_fsm_decls(), name) do
      %{ctors: ctors} ->
        tag = muro_fsm_wire_tag(ctors, value)
        fields = muro_fsm_wire_fields(value)

        case tag && Map.get(ctors, tag) do
          tmpl when is_list(tmpl) and length(tmpl) == length(fields) ->
            muro_fsm_emit_fields(tmpl, fields, name, args, tag)

          _ ->
            :error
        end

      _ ->
        :error
    end
  end

  defp muro_fsm_emit_rec([], _map, acc), do: {:ok, Map.new(acc)}

  defp muro_fsm_emit_rec([{name, ty} | rest], map, acc) do
    case muro_fsm_to_emitted(Map.get(map, name), ty) do
      {:ok, conv} -> muro_fsm_emit_rec(rest, map, [{name, conv} | acc])
      other -> other
    end
  end

  defp muro_fsm_emit_list([], _elem, acc), do: {:ok, :lists.reverse(acc)}

  defp muro_fsm_emit_list([item | rest], elem, acc) do
    case muro_fsm_to_emitted(item, elem) do
      {:ok, conv} -> muro_fsm_emit_list(rest, elem, [conv | acc])
      other -> other
    end
  end

  defp muro_fsm_emit_fields(tmpl, fields, dname, args, tag) do
    zipped = Enum.zip(tmpl, fields)

    Enum.reduce_while(zipped, {:ok, []}, fn {field, got}, {:ok, acc} ->
      case muro_fsm_to_emitted(got, muro_fsm_inst(field, dname, args)) do
        {:ok, conv} -> {:cont, {:ok, acc ++ [conv]}}
        other -> {:halt, other}
      end
    end)
    |> case do
      {:ok, conv} -> {:ok, muro_fsm_pack(tag, conv, :emitted)}
      other -> other
    end
  end

  defp muro_fsm_tag(value) when is_atom(value), do: Atom.to_string(value)

  defp muro_fsm_tag(value) when is_tuple(value) and tuple_size(value) >= 1 do
    tag = elem(value, 0)
    if is_atom(tag), do: Atom.to_string(tag), else: nil
  end

  defp muro_fsm_tag(_), do: nil

  # Host boundary only. The safe map is `elixir_atom_name` for a
  # constructor whose host atom differs from its source name. Prefer
  # that source name when it is a constructor of THIS declaration,
  # otherwise the raw spelling when that spelling is one. Do not call
  # this on a stored source tag. The source name `muro__iszdon` is the
  # host atom of `is-on`, so a second pass would select `is-on`.
  defp muro_fsm_source_tag(ctors, value) when is_map(ctors) do
    case muro_fsm_tag(value) do
      nil ->
        nil

      raw ->
        mapped = Map.get(muro_fsm_safe_to_source(), raw, raw)

        cond do
          Map.has_key?(ctors, mapped) -> mapped
          Map.has_key?(ctors, raw) -> raw
          true -> nil
        end
    end
  end

  # A stored tag is already the source constructor. The atom's name is
  # that constructor. The safe map is not consulted.
  defp muro_fsm_wire_tag(ctors, value) when is_map(ctors) do
    case muro_fsm_tag(value) do
      nil -> nil
      raw -> if Map.has_key?(ctors, raw), do: raw, else: nil
    end
  end

  defp muro_fsm_wire(tag, []), do: String.to_atom(tag)

  defp muro_fsm_wire(tag, fields) when is_list(fields) do
    List.to_tuple([String.to_atom(tag) | fields])
  end

  # A run returns a host atom. Decode it once, against this case's arms.
  defp muro_fsm_emitted_arm(value, arms) when is_list(arms) do
    case muro_fsm_tag(value) do
      nil ->
        nil

      raw ->
        mapped = Map.get(muro_fsm_safe_to_source(), raw, raw)
        names = Enum.map(arms, fn {tag, _} -> tag end)

        cond do
          mapped in names -> mapped
          raw in names -> raw
          true -> nil
        end
    end
  end

  defp muro_fsm_wire_fields(value) when is_atom(value), do: []

  defp muro_fsm_wire_fields(value) when is_tuple(value) and tuple_size(value) >= 1 do
    [_tag | fields] = Tuple.to_list(value)
    fields
  end

  defp muro_fsm_wire_fields(_), do: []

  # The environment holds a source tag. This does not decode a host atom.
  defp muro_fsm_result_tag(value, {:dat, name, _args}) when is_binary(name) do
    case Map.get(muro_fsm_decls(), name) do
      %{ctors: ctors} when is_map(ctors) -> muro_fsm_wire_tag(ctors, value)
      _ -> nil
    end
  end

  defp muro_fsm_result_tag(bit, :bit) when bit in [:b0, :b1], do: Atom.to_string(bit)
  defp muro_fsm_result_tag(_value, _ty), do: nil

  defp muro_fsm_pack(tag, [], :emitted) do
    String.to_atom(Map.get(muro_fsm_source_to_safe(), tag, tag))
  end

  defp muro_fsm_pack(tag, fields, :emitted) do
    atom = String.to_atom(Map.get(muro_fsm_source_to_safe(), tag, tag))
    List.to_tuple([atom | fields])
  end

  defp muro_fsm_call(_fname, _arg), do: :error

  defp muro_fsm_templates,
    do: %{
      "reply-in" =>
        {[],
         {:recv, "priv/muro/http/family.muro:49 session reply-in: first recv Report",
          {:dat, "Report", []}, {:end, "priv/muro/http/family.muro:49 session reply-in: end"}}},
      "reply-out" =>
        {[],
         {:send, "priv/muro/http/family.muro:48 session reply-out: first send Report",
          {:dat, "Report", []}, {:end, "priv/muro/http/family.muro:48 session reply-out: end"}}}
    }

  defp muro_fsm_duals, do: %{}

  defp muro_fsm_ends,
    do: %{
      "reply-in" => "priv/muro/http/family.muro:49 session reply-in: end",
      "reply-out" => "priv/muro/http/family.muro:48 session reply-out: end"
    }

  defp muro_fsm_end(key), do: Map.get(muro_fsm_ends(), key, "")

  # An empty literal map makes Map.get always return its default.
  defp muro_fsm_decls,
    do:
      :maps.from_list([
        {"Act", %{ctors: %{"accept" => [], "reply" => []}, np: 0, order: ["accept", "reply"]}},
        {"Report", %{ctors: %{"ok" => []}, np: 0, order: ["ok"]}}
      ])

  defp muro_fsm_reprs, do: []

  defp muro_fsm_source_to_safe, do: :maps.from_list([])

  defp muro_fsm_safe_to_source, do: :maps.from_list([])

  # One host decode, at this boundary. The result is a source tag.
  # `muro_fsm_payload?` and `muro_fsm_to_emitted` read that tag and do
  # not decode it again.
  defp muro_fsm_admit(:nat, n) when is_integer(n) and n >= 0, do: {:ok, n}
  defp muro_fsm_admit(:nat, _), do: :error

  defp muro_fsm_admit(:bit, bit) when bit in [:b0, :b1], do: {:ok, bit}
  defp muro_fsm_admit(:bit, _), do: :error
  defp muro_fsm_admit(:unit, :tt), do: {:ok, :tt}
  defp muro_fsm_admit(:unit, _), do: :error

  defp muro_fsm_admit({:pair, a, b}, {x, y}) do
    case muro_fsm_from_host(a, x) do
      {:ok, x} ->
        case muro_fsm_from_host(b, y) do
          {:ok, y} -> {:ok, {x, y}}
          :error -> :error
        end

      :error ->
        :error
    end
  end

  defp muro_fsm_admit({:rec, fields}, map) when is_list(fields) and is_map(map) do
    muro_fsm_host_rec(fields, map, [])
  end

  defp muro_fsm_admit({:vec, elem, _ix}, list) when is_list(list) do
    muro_fsm_host_list(list, elem, [])
  end

  defp muro_fsm_admit({:dat, name, args}, value) when is_binary(name) and is_list(args) do
    muro_fsm_host_dat(name, args, value)
  end

  defp muro_fsm_admit(_ty, value), do: {:ok, value}

  defp muro_fsm_host_list([], _elem, acc), do: {:ok, :lists.reverse(acc)}

  defp muro_fsm_host_list([item | rest], elem, acc) do
    case muro_fsm_from_host(elem, item) do
      {:ok, wire} -> muro_fsm_host_list(rest, elem, [wire | acc])
      :error -> :error
    end
  end

  defp muro_fsm_host_rec([], _map, acc), do: {:ok, Map.new(acc)}

  defp muro_fsm_host_rec([{name, ty} | rest], map, acc) do
    case muro_fsm_from_host(ty, Map.get(map, name)) do
      {:ok, wire} -> muro_fsm_host_rec(rest, map, [{name, wire} | acc])
      :error -> :error
    end
  end

  defp muro_fsm_host_dat(name, args, value) do
    case Map.get(muro_fsm_decls(), name) do
      %{ctors: ctors} ->
        tag = muro_fsm_source_tag(ctors, value)
        fields = muro_fsm_wire_fields(value)

        case tag && Map.get(ctors, tag) do
          tmpl when is_list(tmpl) and length(tmpl) == length(fields) ->
            muro_fsm_host_fields(tmpl, fields, name, args, tag, [])

          _ ->
            :error
        end

      _ ->
        :error
    end
  end

  defp muro_fsm_host_fields([], _fields, _dname, _args, tag, acc) do
    {:ok, muro_fsm_wire(tag, :lists.reverse(acc))}
  end

  defp muro_fsm_host_fields([field | tmpl], [got | fields], dname, args, tag, acc) do
    ty = muro_fsm_inst(field, dname, args)

    case muro_fsm_from_host(ty, got) do
      {:ok, wire} -> muro_fsm_host_fields(tmpl, fields, dname, args, tag, [wire | acc])
      :error -> :error
    end
  end

  defp muro_fsm_host(_name), do: nil

  defmodule ReplyOut do
    @moduledoc """
    One end of session `reply-out`. The state is opaque: thread it, compare it
    with ==, and do not depend on its shape. `finish/3`, `finish/4`, and `finish/5` take this end to `done` and resolve the family instance. The outcome `:rerun` leaves that instance unresolved.
    """

    def init, do: MuroHttp.FamilyFsm.muro_fsm_init("reply-out", [])

    def unquote(:send)(state, value) do
      MuroHttp.FamilyFsm.muro_fsm_step("reply-out", :send, state, value)
    end

    def recv(state, value) do
      MuroHttp.FamilyFsm.muro_fsm_step("reply-out", :recv, state, value)
    end

    def done?(state), do: MuroHttp.FamilyFsm.muro_fsm_done?("reply-out", state)

    def expected(state), do: MuroHttp.FamilyFsm.muro_fsm_expected("reply-out", state)

    def check_trace(trace) when is_list(trace) do
      MuroHttp.FamilyFsm.muro_fsm_trace("reply-out", [], trace, false)
    end

    def check_trace(trace, opts) when is_list(trace) and is_list(opts) do
      MuroHttp.FamilyFsm.muro_fsm_trace(
        "reply-out",
        [],
        trace,
        Keyword.get(opts, :complete) == true
      )
    end

    def finish(session_state, family_state, id) do
      case ended(session_state) do
        {:ok, _} -> commit(family_state, id, :resolve)
        {:error, reason} -> {:error, reason}
      end
    end

    def finish(session_state, family_state, id, outcome)
        when is_map(family_state) and is_integer(id) and outcome in [:resolve, :rerun] do
      case ended(session_state) do
        {:ok, _} -> commit(family_state, id, outcome)
        {:error, reason} -> {:error, reason}
      end
    end

    def finish(session_state, family_state, id, outcome)
        when is_map(family_state) and is_integer(id) do
      _ = {session_state, family_state, id}
      {:error, {:outcome, outcome}}
    end

    def finish(session_state, step, family_state, id) do
      finish(session_state, step, family_state, id, :resolve)
    end

    def finish(session_state, step, family_state, id, outcome)
        when outcome in [:resolve, :rerun] do
      case land(session_state, step) do
        {:ok, _} -> commit(family_state, id, outcome)
        {:error, reason} -> {:error, reason}
      end
    end

    def finish(_session_state, _step, _family_state, _id, outcome) do
      {:error, {:outcome, outcome}}
    end

    defp commit(family_state, id, :resolve),
      do: MuroHttp.FamilyFsm.Conns.resolved(family_state, id)

    defp commit(family_state, id, :rerun), do: MuroHttp.FamilyFsm.Conns.retain(family_state, id)

    defp ended(session_state) do
      if MuroHttp.FamilyFsm.muro_fsm_done?("reply-out", session_state) do
        {:ok, session_state}
      else
        {:error, {:unfinished, MuroHttp.FamilyFsm.muro_fsm_expected("reply-out", session_state)}}
      end
    end

    defp land(session_state, {:send, value}) do
      landed(MuroHttp.FamilyFsm.muro_fsm_step("reply-out", :send, session_state, value))
    end

    defp land(session_state, {:recv, value}) do
      landed(MuroHttp.FamilyFsm.muro_fsm_step("reply-out", :recv, session_state, value))
    end

    defp land(_session_state, other), do: {:error, {:step, other}}

    defp landed({:ok, next}) do
      if MuroHttp.FamilyFsm.muro_fsm_done?("reply-out", next) do
        {:ok, next}
      else
        {:error, {:unfinished, MuroHttp.FamilyFsm.muro_fsm_expected("reply-out", next)}}
      end
    end

    defp landed({:error, reason}), do: {:error, reason}
    defp landed(other), do: {:error, {:session, other}}
  end

