  defmodule Conns do
    @moduledoc """
    Dispatcher for family `conns`. The state is opaque: thread it
    and compare it with ==. The key is compared with ==. A call fetches
    that key and does not walk the other keys. `arrive` takes the creation
    index. A kind that is never held opens on arrival. A kind held while
    an earlier instance is unresolved stays held until every earlier
    arrived instance of its key is resolved. A kind held while any other
    instance of its key is open stays held until no other instance of that
    key is open. The instance does not hold itself. A held instance is not
    open, so it does not hold another. When several held instances could
    open, the least creation index opens. An instance that has not
    arrived is not unresolved. `resolved` drops an open instance and lists
    the instances this resolution opens. `withdraw` drops a held instance
    without opening it, and lists the instances that release does. An open
    id is `{:error, {:opened, id}}`. An id that has resolved or been
    withdrawn is `{:error, {:resolved, id}}`. An id this child never
    returned is `{:error, {:unknown, id}}`. The call does not raise. The
    live rows are the open and held instances. Ids come from one counter
    and are not reused, so an id below the counter that is not live has
    left. No row is kept for it, and the state does not grow with ids that
    have left. `resolved` of an id that has left is `{:error, {:unknown,
    id}}`, as it was before `withdraw`: a repeated resolution is not told
    apart from an id this child never returned. A repeat
    of a live instance is an error. A repeat of a forgotten instance is a
    new instance. `finish` takes this family's state, the id, and one
    end's session. `:resolve` drops the instance. `:rerun` keeps the row
    and every held row of its key. It reads that one row and does not walk
    the key. `check_trace` replays arrivals, resolutions, withdrawals,
    reruns, and the session steps of an open instance. A rerun clears
    that id's session, so the next step starts again.
    """

    def new, do: %{n: 0, by: %{}, id: %{}}

    def arrive(state, key, kind, index) do
      with {:ok, st} <- read(state),
           :ok <- index_ok(index),
           {:ok, hold} <- hold_of(kind),
           {:ok, rows} <- rows_of(st, key),
           :ok <- fresh(rows, key, index, st),
           {:ok, phase} <- phase_of(rows, hold, index, st) do
        id = st.n
        rows = Map.put(rows, index, {id, kind, phase})

        next = %{
          st
          | n: id + 1,
            by: Map.put(st.by, key, rows),
            id: Map.put(st.id, id, {key, index})
        }

        {phase, id, next}
      else
        {:error, reason} -> {:error, reason}
      end
    end

    def resolved(state, id) do
      with {:ok, st} <- read(state),
           {:ok, key, index} <- locate(st, id),
           {:ok, rows} <- rows_of(st, key),
           {:ok, _kind} <- open_row(rows, index, id, st),
           {:ok, released, rows} <- take_released(Map.delete(rows, index), key, st) do
        by = if rows == %{}, do: Map.delete(st.by, key), else: Map.put(st.by, key, rows)
        next = %{st | by: by, id: Map.delete(st.id, id)}
        {:ok, released, next}
      else
        {:error, reason} -> {:error, reason}
      end
    end

    def withdraw(state, id) do
      with {:ok, st} <- read(state),
           {:ok, key, index, rows} <- held_only(st, id),
           {:ok, released, rows} <- take_released(Map.delete(rows, index), key, st) do
        by = if rows == %{}, do: Map.delete(st.by, key), else: Map.put(st.by, key, rows)
        next = %{st | by: by, id: Map.delete(st.id, id)}
        {:ok, released, next}
      else
        {:error, reason} -> {:error, reason}
      end
    end

    def finish(state, id, session_state) do
      close(state, id, session_state, :resolve)
    end

    def finish(state, id, session_state, :resolve) do
      close(state, id, session_state, :resolve)
    end

    def finish(state, id, session_state, :rerun) do
      close(state, id, session_state, :rerun)
    end

    def finish(state, id, session_state, outcome) when is_atom(outcome) and outcome != :down do
      _ = {state, id, session_state}
      {:error, {:outcome, outcome}}
    end

    def finish(state, id, session_state, step) do
      step_close(state, id, session_state, step, :resolve)
    end

    def finish(state, id, session_state, step, outcome) when outcome in [:resolve, :rerun] do
      step_close(state, id, session_state, step, outcome)
    end

    def finish(state, id, session_state, step, outcome) do
      _ = {state, id, session_state, step}
      {:error, {:outcome, outcome}}
    end

    @doc false
    def retain(state, id) do
      with {:ok, st} <- read(state),
           {:ok, key, index} <- locate(st, id),
           {:ok, rows} <- rows_of(st, key),
           {:ok, _kind} <- open_row(rows, index, id, st) do
        {:ok, [], st}
      else
        {:error, reason} -> {:error, reason}
      end
    end

    defp close(state, id, session_state, outcome) do
      case ended(session_state) do
        {:ok, _} -> apply_outcome(state, id, outcome)
        {:error, reason} -> {:error, reason}
      end
    end

    defp step_close(state, id, session_state, step, outcome) do
      case land(session_state, step) do
        {:ok, _} -> apply_outcome(state, id, outcome)
        {:error, reason} -> {:error, reason}
      end
    end

    defp apply_outcome(state, id, :resolve), do: resolved(state, id)
    defp apply_outcome(state, id, :rerun), do: retain(state, id)

    defp session_key(%{k: key}) when is_binary(key), do: key
    defp session_key(_state), do: nil

    defp ended(session_state) do
      case session_key(session_state) do
        key when key in ["reply-in", "reply-out"] ->
          if MuroHttp.FamilyFsm.muro_fsm_done?(key, session_state) do
            {:ok, session_state}
          else
            {:error, {:unfinished, MuroHttp.FamilyFsm.muro_fsm_expected(key, session_state)}}
          end

        _ ->
          {:error, {:session, session_state}}
      end
    end

    defp land(session_state, step) do
      case session_key(session_state) do
        key when key in ["reply-in", "reply-out"] -> land_at(key, session_state, step)
        _ -> {:error, {:session, session_state}}
      end
    end

    defp land_at(key, session_state, {:send, value}) do
      landed(key, MuroHttp.FamilyFsm.muro_fsm_step(key, :send, session_state, value))
    end

    defp land_at(key, session_state, {:recv, value}) do
      landed(key, MuroHttp.FamilyFsm.muro_fsm_step(key, :recv, session_state, value))
    end

    defp land_at(_key, _session_state, other), do: {:error, {:step, other}}

    defp landed(key, {:ok, next}) do
      if MuroHttp.FamilyFsm.muro_fsm_done?(key, next) do
        {:ok, next}
      else
        {:error, {:unfinished, MuroHttp.FamilyFsm.muro_fsm_expected(key, next)}}
      end
    end

    defp landed(_key, {:error, reason}), do: {:error, reason}
    defp landed(_key, other), do: {:error, {:session, other}}

    def check_trace(trace) when is_list(trace), do: walk(new(), %{}, trace, 0)
    def check_trace(other), do: {:error, {:trace, other}}

    defp rule(:accept), do: :never
    defp rule(:reply), do: :earlier
    defp rule(_kind), do: :error

    defp read(%{n: n, by: by, id: ids} = st)
         when is_integer(n) and n >= 0 and is_map(by) and is_map(ids) do
      {:ok, st}
    end

    defp read(other), do: {:error, {:state, other}}

    defp index_ok(index) when is_integer(index) and index >= 0, do: :ok
    defp index_ok(index), do: {:error, {:index, index}}

    defp hold_of(kind) do
      case rule(kind) do
        :error -> {:error, {:kind, kind}}
        hold -> {:ok, hold}
      end
    end

    defp rows_of(st, key) do
      case Map.fetch(st.by, key) do
        :error -> {:ok, %{}}
        {:ok, rows} when is_map(rows) -> {:ok, rows}
        {:ok, _} -> {:error, {:state, st}}
      end
    end

    defp fresh(rows, key, index, st) do
      case Map.fetch(rows, index) do
        :error ->
          :ok

        {:ok, {id, kind, phase}}
        when is_integer(id) and id >= 0 and is_atom(kind) and phase in [:open, :held] ->
          {:error, {:duplicate, key, index}}

        {:ok, _} ->
          {:error, {:state, st}}
      end
    end

    defp phase_of(_rows, :never, _index, _st), do: {:ok, :open}

    defp phase_of(rows, :earlier, index, st) do
      case earlier?(rows, index) do
        :clear -> {:ok, :open}
        :blocked -> {:ok, :held}
        :bad -> {:error, {:state, st}}
      end
    end

    defp earlier?(rows, index) do
      Enum.reduce_while(rows, :clear, fn entry, acc ->
        case entry do
          {ix, {id, kind, phase}}
          when is_integer(ix) and ix >= 0 and is_integer(id) and id >= 0 and is_atom(kind) and
                 phase in [:open, :held] ->
            if ix < index, do: {:cont, :blocked}, else: {:cont, acc}

          _ ->
            {:halt, :bad}
        end
      end)
    end

    defp locate(st, id) do
      case Map.fetch(st.id, id) do
        {:ok, {key, index}} when is_integer(index) and index >= 0 -> {:ok, key, index}
        {:ok, _} -> {:error, {:state, st}}
        :error -> {:error, {:unknown, id}}
      end
    end

    defp held_only(st, id) do
      case Map.fetch(st.id, id) do
        {:ok, {key, index}} when is_integer(index) and index >= 0 ->
          case Map.fetch(st.by, key) do
            {:ok, rows} when is_map(rows) ->
              case Map.fetch(rows, index) do
                {:ok, {^id, _kind, :held}} -> {:ok, key, index, rows}
                {:ok, {^id, _kind, :open}} -> {:error, {:opened, id}}
                _ -> {:error, {:state, st}}
              end

            _ ->
              {:error, {:state, st}}
          end

        {:ok, _} ->
          {:error, {:state, st}}

        :error ->
          if left?(st, id), do: {:error, {:resolved, id}}, else: {:error, {:unknown, id}}
      end
    end

    # Ids are handed out from the counter and never reused, so an id
    # below it that is not live has left. Nothing is kept per left id.
    defp left?(st, id), do: is_integer(id) and id >= 0 and id < st.n

    defp open_row(rows, index, id, st) do
      case Map.fetch(rows, index) do
        {:ok, {^id, kind, :open}} when is_atom(kind) -> {:ok, kind}
        {:ok, {^id, kind, :held}} when is_atom(kind) -> {:error, {:held, id}}
        _ -> {:error, {:state, st}}
      end
    end

    defp take_released(rows, key, st) do
      case scan(rows) do
        :bad ->
          {:error, {:state, st}}

        :ok ->
          case held_rows(rows) do
            :bad ->
              {:error, {:state, st}}

            held ->
              released =
                held
                |> Enum.filter(fn {ix, _id, kind} -> not blocked?(rows, kind, ix) end)
                |> one_of_any()
                |> Enum.sort_by(fn {ix, id, _kind} -> {ix, id} end)

              rows =
                Enum.reduce(released, rows, fn {ix, id, kind}, rows ->
                  Map.put(rows, ix, {id, kind, :open})
                end)

              list = Enum.map(released, fn {_ix, id, kind} -> {id, key, kind} end)
              {:ok, list, rows}
          end
      end
    end

    defp held_rows(rows) do
      Enum.reduce_while(rows, [], fn
        {ix, {id, kind, :held}}, acc ->
          if rule(kind) == :earlier,
            do: {:cont, [{ix, id, kind} | acc]},
            else: {:halt, :bad}

        {_ix, {_id, _kind, :open}}, acc ->
          {:cont, acc}

        _, _ ->
          {:halt, :bad}
      end)
    end

    defp scan(rows) do
      if Enum.all?(rows, &row_ok?/1), do: :ok, else: :bad
    end

    defp row_ok?({ix, {id, kind, phase}})
         when is_integer(ix) and ix >= 0 and is_integer(id) and id >= 0 and is_atom(kind) and
                phase in [:open, :held],
         do: true

    defp row_ok?(_row), do: false

    defp blocked?(rows, kind, index) do
      case rule(kind) do
        :earlier ->
          Enum.any?(rows, fn {ix, {_id, _kind, phase}} ->
            ix < index and phase in [:open, :held]
          end)

        _ ->
          true
      end
    end

    defp one_of_any(released), do: released

    defp walk(disp, seen, [], _i), do: leaked(disp, seen)

    defp walk(disp, seen, [{:arrive, key, kind, index} | rest], i) do
      case arrive(disp, key, kind, index) do
        {:error, reason} -> {:error, {i, reason}}
        {_phase, _id, disp} -> walk(disp, seen, rest, i + 1)
      end
    end

    defp walk(disp, seen, [{:resolved, id} | rest], i) do
      case resolve_step(disp, seen, id) do
        {:ok, disp, seen} -> walk(disp, seen, rest, i + 1)
        {:error, reason} -> {:error, {i, reason}}
      end
    end

    defp walk(disp, seen, [{:rerun, id} | rest], i) do
      case rerun_step(disp, seen, id) do
        {:ok, disp, seen} -> walk(disp, seen, rest, i + 1)
        {:error, reason} -> {:error, {i, reason}}
      end
    end

    defp walk(disp, seen, [{:withdraw, id} | rest], i) do
      case withdraw(disp, id) do
        {:ok, _released, disp} -> walk(disp, seen, rest, i + 1)
        {:error, reason} -> {:error, {i, reason}}
      end
    end

    defp walk(disp, seen, [{party, id, action} | rest], i) when is_atom(party) do
      case live(disp, id) do
        {:error, reason} ->
          {:error, {i, reason}}

        {:ok, :held, _key, _kind} ->
          {:error, {i, {:held, id}}}

        {:ok, :open, _key, _kind} ->
          case step_end(seen, party, id, action) do
            {:ok, sess} -> walk(disp, Map.put(seen, {id, party}, sess), rest, i + 1)
            {:error, reason} -> {:error, {i, reason}}
          end
      end
    end

    defp walk(_disp, _seen, [other | _rest], i), do: {:error, {i, {:step, other}}}

    defp resolve_step(disp, seen, id) do
      sessions = sessions_of(seen, id)

      cond do
        sessions == [] ->
          commit(disp, seen, id)

        settled?(sessions) ->
          commit(disp, drop_id(seen, id), id)

        true ->
          {:error, {:unfinished, id}}
      end
    end

    defp sessions_of(seen, id) do
      for {{^id, _party}, sess} <- seen, do: sess
    end

    defp settled?(sessions), do: sessions != [] and Enum.all?(sessions, &at_done?/1)

    defp commit(disp, seen, id) do
      case resolved(disp, id) do
        {:ok, _released, disp} -> {:ok, disp, seen}
        {:error, reason} -> {:error, reason}
      end
    end

    defp rerun_step(disp, seen, id) do
      case retain(disp, id) do
        {:ok, [], disp} ->
          if settled?(sessions_of(seen, id)) do
            {:ok, disp, drop_id(seen, id)}
          else
            {:error, {:unfinished, id}}
          end

        {:error, reason} ->
          {:error, reason}
      end
    end

    defp drop_id(seen, id) do
      Map.reject(seen, fn {{i, _party}, _sess} -> i == id end)
    end

    defp step_end(seen, party, id, action) do
      case party(party) do
        :error ->
          {:error, {:party, party}}

        {session, arity} ->
          prev = Map.get(seen, {id, party})

          cond do
            is_nil(prev) and arity != 0 ->
              {:error, {:session_args, party}}

            true ->
              state =
                case prev do
                  nil -> MuroHttp.FamilyFsm.muro_fsm_init(session, [])
                  {_session, stored} -> stored
                end

              case apply_end(session, state, action) do
                {:ok, next} -> {:ok, {session, next}}
                {:error, reason} -> {:error, reason}
              end
          end
      end
    end

    defp apply_end(session, state, {:send, value}) do
      stepped(MuroHttp.FamilyFsm.muro_fsm_step(session, :send, state, value))
    end

    defp apply_end(session, state, {:recv, value}) do
      stepped(MuroHttp.FamilyFsm.muro_fsm_step(session, :recv, state, value))
    end

    defp apply_end(_session, _state, other), do: {:error, {:step, other}}

    defp stepped({:ok, next}), do: {:ok, next}
    defp stepped({:error, reason}), do: {:error, reason}
    defp stepped(other), do: {:error, {:session, other}}

    defp at_done?({session, state}), do: MuroHttp.FamilyFsm.muro_fsm_done?(session, state)

    defp live(disp, id) do
      case Map.fetch(disp.id, id) do
        {:ok, {key, index}} when is_integer(index) and index >= 0 ->
          case Map.fetch(disp.by, key) do
            {:ok, rows} when is_map(rows) ->
              case Map.fetch(rows, index) do
                {:ok, {^id, kind, phase}} when is_atom(kind) and phase in [:open, :held] ->
                  {:ok, phase, key, kind}

                _ ->
                  {:error, {:state, disp}}
              end

            _ ->
              {:error, {:state, disp}}
          end

        {:ok, _} ->
          {:error, {:state, disp}}

        :error ->
          {:error, {:unknown, id}}
      end
    end

    defp leaked(disp, seen) do
      ids =
        seen
        |> Enum.map(fn {{id, _party}, _sess} -> id end)
        |> Enum.uniq()
        |> Enum.filter(fn id ->
          settled?(sessions_of(seen, id)) and match?({:ok, _phase, _key, _kind}, live(disp, id))
        end)
        |> Enum.sort()

      case ids do
        [] ->
          :ok

        [id | _] ->
          case live(disp, id) do
            {:ok, _phase, key, kind} -> {:error, {:unresolved, id, key, kind}}
            {:error, reason} -> {:error, reason}
          end
      end
    end

    defp party(:host), do: {"reply-in", 0}
    defp party(:peer), do: {"reply-out", 0}
    defp party(_party), do: :error
  end
end
